<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">matcher = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.completed&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # 只关心&quot;已完成&quot;的通知</span></span>
